import { Component, Element, Event, EventEmitter, h, Host, Prop, Watch } from '@stencil/core';

@Component({
  tag: 'groupui-step',
  styleUrl: 'step.scss',
  shadow: true,
})
export class Step {
  /**
   * Groupui icon name
   */
  @Prop({ reflect: true }) readonly icon: string;

  /**
   * sets a custom icon source e.g. '...path/clock-24.svg', overrides icon property if both are set
   */
  @Prop({ reflect: true }) readonly iconSource: string;

  /**
   * hidden attribute
   */
  @Prop({ reflect: true }) readonly number: number;

  /**
   * Defines if the step is done
   */
  @Prop({ reflect: true }) readonly done: boolean = false;

  /**
   * Defines if the step is currently active
   */
  @Prop({ reflect: true }) readonly active: boolean = false;

  /**
   * disables the step
   */
  @Prop({ reflect: true }) readonly disabled: boolean = false;

  /**
   * dispatched when step is getting active
   */
  @Event({ bubbles: false }) groupuiStepActive: EventEmitter<number>;

  /**
   * dispatched when step is getting done
   */
  @Event({ bubbles: false }) groupuiStepDone: EventEmitter<number>;

  @Element() host: HTMLElement;

  @Watch('active')
  emitActive() {
    if (this.active) {
      this.groupuiStepActive.emit(this.number);
    }
  }

  @Watch('done')
  emitDone() {
    if (this.done) {
      this.groupuiStepDone.emit(this.number);
    }
  }

  private getContent() {
    if (this.done) {
      const iconName = this.icon ? this.icon : 'check-24';
      return <groupui-icon name={iconName} src={this.iconSource}></groupui-icon>;
    }
    return this.icon || this.iconSource ? (
      <groupui-icon name={this.icon} src={this.iconSource}></groupui-icon>
    ) : (
      this.number
    );
  }

  render() {
    return (
      <Host>
        <div
          role="listitem"
          class="step"
          aria-current={this.active ? 'true' : 'false'}
          aria-disabled={this.disabled && 'true'}
          aria-label={`Step ${this.number} ${this.done ? ', completed' : ''}`}
        >
          <div aria-hidden="true" class="step-indicator">
            <div class="step-indicator-content">{this.getContent()}</div>
          </div>
          <div id="title" class="step-title">
            <slot />
          </div>
        </div>
      </Host>
    );
  }
}
